#!/bin/sh
# Sentinel worker bootstrap.
#
# Generated by the controller for ONE worker host. It holds no credential: the
# enrollment secret (and, over Tailcat, the controller's Tailcat address) is read
# from a 0600 file or from standard input, never from this file, a URL, an
# argument or the environment. Nothing downloaded is ever piped into a shell:
# every download lands in a root-owned staging directory, is checked against the
# SHA-256 pinned below, and only then installed.
#
#   sh sentinel-worker-bootstrap.sh help
#
# Exit status: 0 done, 1 failed, 2 this host is not supported (said out loud),
# 64 usage error.

set -eu
umask 077
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH

# --- generated settings begin ---
BOOTSTRAP_FORMAT=''
TRANSPORT=''
CONTROLLER_ADDR=''
CONTROLLER_FINGERPRINT=''
API_URL=''
RELEASE_VERSION=''
WORKER_URL_X86_64=''
WORKER_SHA256_X86_64=''
WORKER_URL_AARCH64=''
WORKER_SHA256_AARCH64=''
TAILCAT_VERSION=''
TAILCAT_URL_X86_64=''
TAILCAT_SHA256_X86_64=''
TAILCAT_URL_AARCH64=''
TAILCAT_SHA256_AARCH64=''
TAILCAT_DERPMAP_URL=''
TAILCAT_REGION=''
# --- generated settings end ---

ACCOUNT=sentinel-worker
UNIT=sentinel-worker
PREFIX=/opt/sentinel-worker
CONF_DIR=/etc/sentinel-worker
CONF_FILE=/etc/sentinel-worker/worker.toml
DATA_DIR=/var/lib/sentinel-worker
UNIT_FILE=/etc/systemd/system/sentinel-worker.service
STATE_FILE=/opt/sentinel-worker/install.state
LOCK_DIR=/run/sentinel-worker-bootstrap.lock
LINK_PORT=7443
MAX_WORKER_BYTES=268435456
MAX_TAILCAT_BYTES=134217728
SUBID_SIZE=65536
SUBID_FLOOR=100000

STAGE=''
LOCKED=0
TOUCHED=0
FRESH=0
SWITCHED=0
OLD_REL=''
OLD_PREV=''
NEW_REL=''
ARCH=''
DOWNLOADER=''
WORKER_URL=''
WORKER_SHA256=''
TAILCAT_URL=''
TAILCAT_SHA256=''
SECRET=''
TC_ADDRESS=''
ENROLLED_ID=''

say() { printf '%s\n' "sentinel-worker: $*" >&2; }
die() {
    say "error: $*"
    exit 1
}
refuse() {
    say "refused: $*"
    say "nothing was changed on this host"
    exit 2
}
usage_error() {
    say "usage error: $*"
    say "run 'sh $0 help' for the commands"
    exit 64
}

usage() {
    cat <<'EOF'
Sentinel worker bootstrap

  sh sentinel-worker-bootstrap.sh install   [--name NAME] [--secret-file FILE | --secret-stdin] [--no-start]
  sh sentinel-worker-bootstrap.sh check
  sh sentinel-worker-bootstrap.sh identity
  sh sentinel-worker-bootstrap.sh rollback
  sh sentinel-worker-bootstrap.sh uninstall [--keep-data]
  sh sentinel-worker-bootstrap.sh help

install      download the pinned worker (and Tailcat helper), verify their digests, create
             the 'sentinel-worker' account and directories, write the configuration and the
             systemd unit, then start the worker. Run it again with a newer script to upgrade;
             the previous release is kept for 'rollback'. A fresh install needs the
             enrollment secret from --secret-file (a regular file, mode 0600 or tighter, owned
             by root) or from standard input (--secret-stdin). The input has the secret on its
             first line and, for a Tailcat enrollment, the controller's Tailcat address on its
             second. The worker deletes its enrollment file once it has enrolled.
check        run the host checks only; changes nothing.
identity     print the worker id and, for Tailcat, the line 'nodekey:<64 hex> wrk_<id>' that the
             controller's allow list takes.
rollback     switch back to the previous release and restart.
uninstall    stop and remove the service, files and account this script created; the worker's
             data directory (identity, caches) goes too unless --keep-data. Ask the controller
             to uninstall the worker first so accepted work finishes.
EOF
}

# ---- state ---------------------------------------------------------------

state_get() {
    [ -f "$STATE_FILE" ] || return 0
    sed -n "s/^$1=//p" "$STATE_FILE" | head -n 1
}

state_put() {
    # key value: replace or append one line of the root-owned install record.
    tmp="$STATE_FILE.tmp"
    if [ -f "$STATE_FILE" ]; then
        grep -v "^$1=" "$STATE_FILE" >"$tmp" || true
    else
        : >"$tmp"
    fi
    printf '%s=%s\n' "$1" "$2" >>"$tmp"
    chmod 0644 "$tmp"
    mv -f "$tmp" "$STATE_FILE"
}

# ---- host checks ---------------------------------------------------------

need() {
    command -v "$1" >/dev/null 2>&1 || refuse "this host lacks '$1'$2"
}

podman_major() {
    podman --version 2>/dev/null | awk '{ split($NF, v, "."); print v[1] + 0 }'
}

check_host() {
    # argument: 1 when root is required
    [ "$(uname -s)" = Linux ] || refuse "this script installs a Linux worker; this host runs $(uname -s)"
    case $(uname -m) in
        x86_64 | amd64) ARCH=x86_64 ;;
        aarch64 | arm64) ARCH=aarch64 ;;
        *) refuse "unsupported CPU architecture $(uname -m); workers run on x86_64 and aarch64" ;;
    esac
    case $ARCH in
        x86_64)
            WORKER_URL=$WORKER_URL_X86_64
            WORKER_SHA256=$WORKER_SHA256_X86_64
            TAILCAT_URL=$TAILCAT_URL_X86_64
            TAILCAT_SHA256=$TAILCAT_SHA256_X86_64
            ;;
        aarch64)
            WORKER_URL=$WORKER_URL_AARCH64
            WORKER_SHA256=$WORKER_SHA256_AARCH64
            TAILCAT_URL=$TAILCAT_URL_AARCH64
            TAILCAT_SHA256=$TAILCAT_SHA256_AARCH64
            ;;
    esac
    if [ -z "$WORKER_URL" ] || [ -z "$WORKER_SHA256" ]; then
        refuse "this controller publishes no worker release for $ARCH"
    fi
    case $TRANSPORT in
        tailcat)
            if [ -z "$TAILCAT_URL" ] || [ -z "$TAILCAT_SHA256" ]; then
                refuse "this controller pins no Tailcat helper for $ARCH; ask for a direct TLS enrollment"
            fi
            ;;
        direct) ;;
        *) die "this script was generated without a transport" ;;
    esac
    if [ "$1" = 1 ] && [ "$(id -u)" -ne 0 ]; then
        refuse "run it as root, for example: sudo sh $0 $CMD ..."
    fi
    [ -d /run/systemd/system ] || refuse "systemd is not this host's init system (/run/systemd/system is missing); the worker is installed as a systemd service"
    for tool in systemctl loginctl tar gzip sha256sum awk sed grep head install mktemp useradd usermod userdel getent runuser stat df wc tr env; do
        need "$tool" ""
    done
    if command -v curl >/dev/null 2>&1; then
        DOWNLOADER=curl
    elif command -v wget >/dev/null 2>&1; then
        DOWNLOADER=wget
    else
        refuse "this host has neither 'curl' nor 'wget' to download the release"
    fi
    need podman ": the worker runs jobs in rootless Podman containers"
    [ "$(podman_major)" -ge 4 ] 2>/dev/null || refuse "Podman 4 or newer is required (found: $(podman --version 2>&1 | head -n 1))"
    need newuidmap " (package 'uidmap'): rootless Podman needs it"
    need newgidmap " (package 'uidmap'): rootless Podman needs it"
    if [ -r /proc/sys/user/max_user_namespaces ] && [ "$(cat /proc/sys/user/max_user_namespaces)" -le 0 ]; then
        refuse "user namespaces are disabled (user.max_user_namespaces is 0); rootless Podman cannot run"
    fi
    [ -f /sys/fs/cgroup/cgroup.controllers ] || refuse "cgroup v2 is required (the worker enforces job limits through it); this host runs cgroup v1"
}

# ---- locking and cleanup -------------------------------------------------

take_lock() {
    mkdir "$LOCK_DIR" 2>/dev/null || die "another run holds $LOCK_DIR; remove it only when no bootstrap is running"
    LOCKED=1
}

on_exit() {
    rc=$?
    trap - EXIT
    if [ "$rc" -ne 0 ] && [ "$TOUCHED" = 1 ]; then
        say "the install failed (exit $rc); undoing what this run changed"
        if [ -n "$ENROLLED_ID" ]; then
            say "the controller had already enrolled worker $ENROLLED_ID; ask a platform administrator to uninstall it there (the enrollment cannot be reused)"
        fi
        undo_install || say "could not undo everything; run 'sh $0 uninstall' to finish"
    fi
    if [ -n "$STAGE" ]; then
        rm -rf -- "$STAGE"
    fi
    if [ "$LOCKED" = 1 ]; then
        rmdir "$LOCK_DIR" 2>/dev/null || true
    fi
    exit "$rc"
}

undo_install() {
    if [ "$FRESH" = 1 ]; then
        remove_installation 1
        return 0
    fi
    if [ "$SWITCHED" = 1 ] && [ -n "$OLD_REL" ] && [ -d "$PREFIX/releases/$OLD_REL" ]; then
        ln -sfn "releases/$OLD_REL" "$PREFIX/current"
        if [ -n "$OLD_PREV" ]; then
            ln -sfn "$OLD_PREV" "$PREFIX/previous"
        else
            rm -f -- "$PREFIX/previous"
        fi
        state_put release "$OLD_REL"
        systemctl restart "$UNIT" || true
        wait_active 30 || say "the previous release $OLD_REL did not come back up either (see: journalctl -u $UNIT)"
    fi
    if [ -n "$NEW_REL" ] && [ "$NEW_REL" != "$OLD_REL" ]; then
        rm -rf -- "${PREFIX:?}/releases/$NEW_REL"
    fi
}

# ---- download and verify -------------------------------------------------

download() {
    # url dest max_bytes
    if [ "$DOWNLOADER" = curl ]; then
        curl --fail --silent --show-error --location --proto '=http,https' --proto-redir '=https' \
            --max-redirs 3 --connect-timeout 20 --max-time 1800 --max-filesize "$3" \
            --output "$2" --url "$1" || return 1
    else
        wget --quiet --max-redirect=3 --timeout=30 --tries=2 --output-document="$2" "$1" || return 1
    fi
    size=$(wc -c <"$2" | tr -d ' ')
    if [ "$size" -gt "$3" ]; then
        rm -f -- "$2"
        return 1
    fi
}

fetch_verified() {
    # label url sha256 dest max_bytes
    say "downloading $1"
    download "$2" "$4" "$5" || die "cannot download $1 from the controller's release location"
    actual=$(sha256sum "$4" | awk '{ print $1 }')
    if [ "$actual" != "$3" ]; then
        rm -f -- "$4"
        die "$1 does not match the digest pinned by the controller (expected $3, got $actual); nothing was installed"
    fi
    say "verified $1 (sha256 $3)"
}

# ---- enrollment input ----------------------------------------------------

read_input() {
    case $SECRET_SOURCE in
        path)
            if [ ! -f "$SECRET_FILE" ] || [ -L "$SECRET_FILE" ]; then
                die "--secret-file must be a regular file, not a link or a directory"
            fi
            owner=$(stat -c '%u' "$SECRET_FILE")
            [ "$owner" -eq 0 ] || die "--secret-file must be owned by root"
            mode=$(stat -c '%a' "$SECRET_FILE")
            case $mode in
                *00) ;;
                *) die "--secret-file is mode $mode; make it 0600 (chmod 600) so no other account can read it" ;;
            esac
            input=$(head -c 2048 -- "$SECRET_FILE")
            ;;
        stdin)
            if [ -t 0 ]; then
                say "enrollment secret (input is hidden):"
                stty -echo 2>/dev/null || true
                IFS= read -r l1 || l1=''
                if [ "$TRANSPORT" = tailcat ] && [ -z "$API_URL" ]; then
                    say "controller Tailcat address (input is hidden):"
                    IFS= read -r l2 || l2=''
                else
                    l2=''
                fi
                stty echo 2>/dev/null || true
                input=$(printf '%s\n%s\n' "$l1" "$l2")
                l1=''
                l2=''
            else
                input=$(head -c 2048)
            fi
            ;;
        *) return 0 ;;
    esac
    SECRET=$(printf '%s\n' "$input" | sed -n '1p' | tr -d '\r\t ')
    TC_ADDRESS=$(printf '%s\n' "$input" | sed -n '2p' | tr -d '\r\t ')
    input=''
    case $SECRET in
        sntl_*) ;;
        *) die "the first line of the enrollment input is not an enrollment secret (it must start with sntl_)" ;;
    esac
    printf '%s\n' "${SECRET#sntl_}" | grep -Eq '^[0-9a-f]{64}$' ||
        die "the enrollment secret is malformed (sntl_ followed by 64 hex characters)"
    if [ -n "$API_URL" ]; then
        # The controller answers the redemption with its Tailcat address: nothing more to read.
        TC_ADDRESS=''
    elif [ "$TRANSPORT" = tailcat ]; then
        printf '%s\n' "$TC_ADDRESS" | grep -Eq '^tc[A-Za-z0-9_-]{20,254}$' ||
            die "a Tailcat enrollment needs the controller's Tailcat address (tc...) on the second line of the input"
    else
        TC_ADDRESS=''
    fi
}

# ---- account and directories ---------------------------------------------

next_subid_start() {
    awk -F: -v floor="$SUBID_FLOOR" '
        { end = $2 + $3; if (end > top) top = end }
        END { print (top < floor ? floor : top) }
    ' /etc/subuid /etc/subgid 2>/dev/null || printf '%s\n' "$SUBID_FLOOR"
}

nologin_shell() {
    for s in /usr/sbin/nologin /sbin/nologin /usr/bin/nologin /bin/false; do
        if [ -x "$s" ]; then
            printf '%s\n' "$s"
            return 0
        fi
    done
    printf '%s\n' /bin/false
}

create_account() {
    if getent passwd "$ACCOUNT" >/dev/null 2>&1; then
        return 0
    fi
    useradd --system --user-group --home-dir "$DATA_DIR" --no-create-home --shell "$(nologin_shell)" "$ACCOUNT"
    state_put created_account 1
}

allocate_subids() {
    if grep -q "^$ACCOUNT:" /etc/subuid 2>/dev/null && grep -q "^$ACCOUNT:" /etc/subgid 2>/dev/null; then
        return 0
    fi
    start=$(next_subid_start)
    end=$((start + SUBID_SIZE - 1))
    usermod --add-subuids "$start-$end" --add-subgids "$start-$end" "$ACCOUNT" ||
        die "cannot allocate subordinate UID/GID ranges for $ACCOUNT (rootless Podman needs them)"
}

enable_linger() {
    if [ -e "/var/lib/systemd/linger/$ACCOUNT" ]; then
        return 0
    fi
    loginctl enable-linger "$ACCOUNT" || die "cannot enable lingering for $ACCOUNT (rootless Podman needs its user manager at boot)"
    state_put enabled_linger 1
}

# ---- files ---------------------------------------------------------------

# Redeem the enrollment over HTTPS with the installed worker: it generates this host's identities as the
# service account, binds them at the controller in one step and writes the configuration, which is then
# installed root-owned. The secret travels on a pipe into the worker's standard input.
enroll_over_https() {
    bin=$1
    uid=$2
    staged="$DATA_DIR/worker.toml.staged"
    rm -f -- "$staged"
    set -- --api-url "$API_URL" --data-dir "$DATA_DIR" --config "$staged" --name "$WORKER_NAME" --secret-stdin
    if [ "$TRANSPORT" = tailcat ]; then
        set -- "$@" --tailcat-binary "$PREFIX/tailcat/tailcat" --tailcat-sha256 "$TAILCAT_SHA256" --tailcat-port "$LINK_PORT"
        if [ -n "$TAILCAT_DERPMAP_URL" ]; then
            set -- "$@" --derpmap-url "$TAILCAT_DERPMAP_URL"
        fi
        if [ -n "$TAILCAT_REGION" ]; then
            set -- "$@" --region "$TAILCAT_REGION"
        fi
    fi
    printf '%s\n' "$SECRET" | runuser -u "$ACCOUNT" -- env HOME="$DATA_DIR" XDG_RUNTIME_DIR="/run/user/$uid" "$bin" worker enroll "$@" ||
        die "enrolling with the controller failed (see the message above); nothing was installed"
    SECRET=''
    if [ -s "$DATA_DIR/worker.id" ]; then
        ENROLLED_ID=$(head -n 1 "$DATA_DIR/worker.id")
    fi
    install -m 0640 -o root -g "$ACCOUNT" "$staged" "$CONF_FILE"
    rm -f -- "$staged"
}

write_config() {
    tmp="$CONF_FILE.new"
    {
        printf '# Written by the Sentinel worker bootstrap. Ceilings and priority are set on the controller.\n'
        printf 'data_dir = "%s"\n' "$DATA_DIR"
        printf 'log_format = "text"\n'
        printf 'log_level = "info"\n'
        if [ "$TRANSPORT" = tailcat ]; then
            printf 'controller = "127.0.0.1:%s"\n' "$LINK_PORT"
        else
            printf 'controller = "%s"\n' "$CONTROLLER_ADDR"
        fi
        printf 'controller_fingerprint = "%s"\n' "$CONTROLLER_FINGERPRINT"
        printf 'worker_name = "%s"\n' "$WORKER_NAME"
        printf 'enrollment_file = "%s/enrollment"\n' "$DATA_DIR"
        if [ "$TRANSPORT" = tailcat ]; then
            printf 'tailcat_address = "%s"\n' "$TC_ADDRESS"
            printf '\n[tailcat]\nenabled = true\n'
            printf 'binary = "%s/tailcat/tailcat"\n' "$PREFIX"
            printf 'sha256 = "%s"\n' "$TAILCAT_SHA256"
            printf 'listen_port = %s\n' "$LINK_PORT"
            if [ -n "$TAILCAT_DERPMAP_URL" ]; then
                printf 'derpmap_url = "%s"\n' "$TAILCAT_DERPMAP_URL"
            fi
            if [ -n "$TAILCAT_REGION" ]; then
                printf 'region = "%s"\n' "$TAILCAT_REGION"
            fi
        fi
    } >"$tmp"
    chown "root:$ACCOUNT" "$tmp"
    chmod 0640 "$tmp"
    mv -f "$tmp" "$CONF_FILE"
}

write_unit() {
    uid=$1
    tmp="$UNIT_FILE.new"
    cat >"$tmp" <<EOF
# Written by the Sentinel worker bootstrap.
[Unit]
Description=Sentinel worker
Documentation=file://$CONF_FILE
After=network-online.target user@$uid.service
Wants=network-online.target user@$uid.service

[Service]
Type=simple
User=$ACCOUNT
Group=$ACCOUNT
Environment=XDG_RUNTIME_DIR=/run/user/$uid
ExecStart=$PREFIX/current/sentinel worker --config $CONF_FILE
Restart=on-failure
RestartSec=2
LimitNOFILE=1048576

[Install]
WantedBy=multi-user.target
EOF
    chmod 0644 "$tmp"
    mv -f "$tmp" "$UNIT_FILE"
}

wait_active() {
    n=0
    while [ "$n" -lt "$1" ]; do
        if systemctl is-active --quiet "$UNIT"; then
            sleep 3
            systemctl is-active --quiet "$UNIT" && return 0
            return 1
        fi
        n=$((n + 1))
        sleep 1
    done
    return 1
}

prune_releases() {
    keep_a=$(basename "$(readlink "$PREFIX/current" 2>/dev/null || true)")
    keep_b=$(basename "$(readlink "$PREFIX/previous" 2>/dev/null || true)")
    for dir in "$PREFIX"/releases/*; do
        [ -d "$dir" ] || continue
        name=$(basename "$dir")
        if [ "$name" != "$keep_a" ] && [ "$name" != "$keep_b" ]; then
            rm -rf -- "$dir"
        fi
    done
}

# ---- commands ------------------------------------------------------------

cmd_check() {
    check_host 0
    say "ok: this host can run the worker ($ARCH, podman $(podman_major).x, transport $TRANSPORT, release $RELEASE_VERSION)"
}

cmd_install() {
    WORKER_NAME=''
    SECRET_SOURCE=''
    SECRET_FILE=''
    NO_START=0
    while [ $# -gt 0 ]; do
        case $1 in
            --name)
                [ $# -ge 2 ] || usage_error "--name needs a value"
                WORKER_NAME=$2
                shift 2
                ;;
            --secret-file)
                [ $# -ge 2 ] || usage_error "--secret-file needs a path"
                SECRET_SOURCE=path
                SECRET_FILE=$2
                shift 2
                ;;
            --secret-stdin)
                SECRET_SOURCE=stdin
                shift
                ;;
            --no-start)
                NO_START=1
                shift
                ;;
            *) usage_error "unknown option '$1' for install" ;;
        esac
    done
    check_host 1

    existing=''
    if [ -f "$STATE_FILE" ]; then
        existing=$(state_get transport)
        [ "$existing" = "$TRANSPORT" ] ||
            die "this host runs a $existing worker; this script installs a $TRANSPORT one. Uninstall first to change transport"
        if [ -z "$WORKER_NAME" ]; then
            WORKER_NAME=$(state_get name)
        fi
    else
        FRESH=1
        [ -n "$SECRET_SOURCE" ] ||
            usage_error "a fresh install needs the enrollment secret: --secret-file FILE or --secret-stdin"
        if getent passwd "$ACCOUNT" >/dev/null 2>&1; then
            refuse "an account named '$ACCOUNT' already exists and was not created by this script; remove or rename it first"
        fi
        for leftover in "$PREFIX" "$CONF_DIR" "$UNIT_FILE" "$DATA_DIR"; do
            if [ -e "$leftover" ]; then
                refuse "$leftover already exists but no install record does. A kept data directory holds the identity of a worker that was uninstalled and revoked; remove it (or the leftover) and run again"
            fi
        done
    fi
    if [ -z "$WORKER_NAME" ]; then
        WORKER_NAME=$(hostname -s 2>/dev/null || uname -n)
    fi
    WORKER_NAME=$(printf '%s' "$WORKER_NAME" | tr -c 'A-Za-z0-9._-' '-' | head -c 128)
    [ -n "$WORKER_NAME" ] || WORKER_NAME=worker
    take_lock
    trap on_exit EXIT
    read_input

    STAGE=$(mktemp -d /var/tmp/sentinel-worker-bootstrap.XXXXXX)
    chmod 0700 "$STAGE"
    fetch_verified "the Sentinel worker $RELEASE_VERSION ($ARCH)" "$WORKER_URL" "$WORKER_SHA256" "$STAGE/worker.tar.gz" "$MAX_WORKER_BYTES"
    top=$(basename "$WORKER_URL")
    top=${top%.tar.gz}
    tar -xzf "$STAGE/worker.tar.gz" -C "$STAGE" "$top/bin/sentinel" 2>/dev/null ||
        die "the worker archive does not hold $top/bin/sentinel"
    if [ ! -f "$STAGE/$top/bin/sentinel" ] || [ -L "$STAGE/$top/bin/sentinel" ]; then
        die "the worker archive's bin/sentinel is not a regular file"
    fi
    if [ "$TRANSPORT" = tailcat ]; then
        fetch_verified "the Tailcat helper $TAILCAT_VERSION ($ARCH)" "$TAILCAT_URL" "$TAILCAT_SHA256" "$STAGE/tailcat" "$MAX_TAILCAT_BYTES"
    fi

    # Everything below changes the host. From here a failure undoes this run.
    NEW_REL="$RELEASE_VERSION-$(printf '%.12s' "$WORKER_SHA256")"
    OLD_REL=$(basename "$(readlink "$PREFIX/current" 2>/dev/null || true)")
    [ "$OLD_REL" != . ] || OLD_REL=''
    OLD_PREV=$(readlink "$PREFIX/previous" 2>/dev/null || true)
    TOUCHED=1
    install -d -m 0755 -o root -g root "$PREFIX" "$PREFIX/releases"
    [ -f "$STATE_FILE" ] || printf 'format=1\n' >"$STATE_FILE"
    create_account
    allocate_subids
    enable_linger
    uid=$(id -u "$ACCOUNT")
    install -d -m 0700 -o "$ACCOUNT" -g "$ACCOUNT" "$DATA_DIR"
    install -d -m 0750 -o root -g "$ACCOUNT" "$CONF_DIR"
    install -d -m 0755 -o root -g root "$PREFIX/releases/$NEW_REL"
    install -m 0755 -o root -g root "$STAGE/$top/bin/sentinel" "$PREFIX/releases/$NEW_REL/sentinel"
    if [ "$TRANSPORT" = tailcat ]; then
        install -d -m 0755 -o root -g root "$PREFIX/tailcat"
        install -m 0755 -o root -g root "$STAGE/tailcat" "$PREFIX/tailcat/tailcat"
    fi
    if [ -n "$SECRET" ] && [ -n "$API_URL" ]; then
        enroll_over_https "$PREFIX/releases/$NEW_REL/sentinel" "$uid"
    elif [ -n "$SECRET" ]; then
        enrollment="$DATA_DIR/enrollment"
        rm -f -- "$enrollment"
        install -m 0600 -o "$ACCOUNT" -g "$ACCOUNT" /dev/null "$enrollment"
        printf '%s\n' "$SECRET" >"$enrollment"
        SECRET=''
    fi
    if [ ! -f "$CONF_FILE" ] && [ -n "$API_URL" ]; then
        die "$CONF_FILE is missing and there is no enrollment secret to rebuild it; uninstall and install again"
    elif [ "$FRESH" = 1 ] || [ ! -f "$CONF_FILE" ]; then
        write_config
    else
        say "kept the existing $CONF_FILE; local settings in it survive an upgrade"
    fi
    write_unit "$uid"
    # Validate the configuration with the new binary, as the service account, before switching to it.
    runuser -u "$ACCOUNT" -- "$PREFIX/releases/$NEW_REL/sentinel" worker --check --config "$CONF_FILE" >/dev/null ||
        die "the new worker rejected its configuration (sentinel worker --check failed)"
    if [ -n "$OLD_REL" ] && [ "$OLD_REL" != "$NEW_REL" ]; then
        ln -sfn "releases/$OLD_REL" "$PREFIX/previous"
    fi
    ln -sfn "releases/$NEW_REL" "$PREFIX/current"
    SWITCHED=1
    state_put release "$NEW_REL"
    state_put version "$RELEASE_VERSION"
    state_put transport "$TRANSPORT"
    state_put name "$WORKER_NAME"
    systemctl daemon-reload
    if [ "$NO_START" = 1 ]; then
        systemctl enable "$UNIT" >/dev/null 2>&1 || die "cannot enable the $UNIT service"
        say "installed $NEW_REL; not started (--no-start). Start it with: systemctl start $UNIT"
    else
        systemctl enable "$UNIT" >/dev/null 2>&1 || die "cannot enable the $UNIT service"
        systemctl restart "$UNIT" || die "cannot start the $UNIT service"
        wait_active 30 || die "the $UNIT service did not stay up (see: journalctl -u $UNIT)"
        wait_identity || say "the worker has not written its identity yet (see: journalctl -u $UNIT)"
    fi
    state_put complete 1
    TOUCHED=0
    prune_releases
    say "installed Sentinel worker $RELEASE_VERSION ($TRANSPORT) as '$WORKER_NAME'"
    if [ -f "$DATA_DIR/worker.id" ]; then
        say "worker id: $(head -n 1 "$DATA_DIR/worker.id")"
    fi
    if [ "$TRANSPORT" = tailcat ] && [ -z "$API_URL" ]; then
        say "the controller admits this worker's Tailcat key once you authorize it for the enrollment it was issued from: sh $0 identity | sentinel admin tailcat authorize --enrollment <tok_ id> --data-dir <controller data dir>"
    fi
}

wait_identity() {
    n=0
    while [ "$n" -lt 20 ]; do
        if [ -s "$DATA_DIR/worker.id" ] && [ -s "$DATA_DIR/worker.crt" ]; then
            return 0
        fi
        n=$((n + 1))
        sleep 1
    done
    return 1
}

cmd_identity() {
    [ -f "$STATE_FILE" ] || die "no worker is installed on this host"
    [ -s "$DATA_DIR/worker.id" ] || die "the worker has not started yet; there is no identity to print"
    id=$(head -n 1 "$DATA_DIR/worker.id")
    if [ "$(state_get transport)" = tailcat ]; then
        key_file="$DATA_DIR/tailcat/client-default.nodekey"
        [ -s "$key_file" ] || die "the worker has not generated its Tailcat node key yet; start it and retry"
        key=$(head -n 1 "$key_file" | tr -d '\r\t ')
        printf '%s %s\n' "$key" "$id"
    else
        printf '%s\n' "$id"
    fi
}

cmd_rollback() {
    check_root_only
    take_lock
    trap on_exit EXIT
    if [ ! -L "$PREFIX/previous" ] || [ ! -d "$PREFIX/$(readlink "$PREFIX/previous")" ]; then
        die "there is no previous release to roll back to"
    fi
    bin="$PREFIX/current/sentinel"
    if [ -x "$bin" ]; then
        if "$bin" worker rollback; then
            return 0
        else
            rc=$?
        fi
        # 1 is the worker's own report that the switch failed or the old release did not stay up (it restored
        # the running one); anything else means it cannot do the switch at all.
        [ "$rc" -ne 1 ] || die "the rollback failed (see above)"
        say "the installed worker cannot roll itself back (exit $rc); using this script's own rollback"
    fi
    current=$(readlink "$PREFIX/current")
    previous=$(readlink "$PREFIX/previous")
    ln -sfn "$previous" "$PREFIX/current"
    ln -sfn "$current" "$PREFIX/previous"
    state_put release "$(basename "$previous")"
    systemctl restart "$UNIT" || true
    if ! wait_active 30; then
        ln -sfn "$current" "$PREFIX/current"
        ln -sfn "$previous" "$PREFIX/previous"
        state_put release "$(basename "$current")"
        systemctl restart "$UNIT" || true
        die "the previous release did not stay up; restored $(basename "$current")"
    fi
    say "rolled back to $(basename "$previous"); $(basename "$current") is kept for another rollback"
}

check_root_only() {
    [ "$(uname -s)" = Linux ] || refuse "this script manages a Linux worker; this host runs $(uname -s)"
    [ "$(id -u)" -eq 0 ] || refuse "run it as root, for example: sudo sh $0 $CMD"
    [ -f "$STATE_FILE" ] || die "no worker is installed on this host"
}

# The last line of an uninstall: removing the files does not tell the controller, and what the controller does
# when told (revoke, end the session, release the leases, drop the Tailcat allow entry) is part of the removal.
controller_report() {
    # arguments: the worker identifier (or empty), 1 if the host held a Tailcat key
    if [ -z "$1" ]; then
        say "no worker identity was found on this host, so the controller holds nothing to revoke for it"
        return 0
    fi
    extra=
    [ "$2" != 1 ] || extra=", removes its Tailcat allow entry"
    say "the controller still lists worker $1 until a platform administrator requests its uninstall there (POST /api/v1/admin/workers/$1/uninstall); that revokes it, ends its session, releases the leases it holds through the controller's reconciliation$extra and refuses it if it ever dials again"
}

remove_installation() {
    # argument: 1 to remove the data directory too
    created=$(state_get created_account)
    linger=$(state_get enabled_linger)
    # Read before the data directory goes: the controller knows this machine by this identifier.
    worker_id=$(head -n 1 "$DATA_DIR/worker.id" 2>/dev/null | tr -cd 'A-Za-z0-9_-' || true)
    case $worker_id in
        wrk_*) [ "${#worker_id}" -le 64 ] || worker_id= ;;
        *) worker_id= ;;
    esac
    has_tailcat=0
    [ ! -d "$DATA_DIR/tailcat" ] || has_tailcat=1
    # The installed worker removes what the install made; this function finishes the job when it cannot run
    # (a release that predates the command, a broken binary) or stops partway.
    bin="$PREFIX/current/sentinel"
    if [ -x "$bin" ]; then
        if [ "$1" = 1 ]; then
            "$bin" worker uninstall && return 0
        else
            "$bin" worker uninstall --keep-data && return 0
        fi
        say "the installed worker could not finish the removal; finishing it with this script"
    fi
    if command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]; then
        systemctl stop "$UNIT" 2>/dev/null || true
        systemctl disable "$UNIT" >/dev/null 2>&1 || true
    fi
    rm -f -- "$UNIT_FILE" "$UNIT_FILE.new"
    if command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]; then
        systemctl daemon-reload 2>/dev/null || true
    fi
    rm -rf -- "$PREFIX" "$CONF_DIR"
    if [ "$1" = 1 ]; then
        rm -rf -- "$DATA_DIR"
    fi
    if [ "$linger" = 1 ]; then
        loginctl disable-linger "$ACCOUNT" 2>/dev/null || true
    fi
    if [ "$created" = 1 ] && getent passwd "$ACCOUNT" >/dev/null 2>&1; then
        userdel "$ACCOUNT" 2>/dev/null || say "could not remove the '$ACCOUNT' account"
    fi
    controller_report "$worker_id" "$has_tailcat"
}

cmd_uninstall() {
    keep_data=0
    while [ $# -gt 0 ]; do
        case $1 in
            --keep-data)
                keep_data=1
                shift
                ;;
            *) usage_error "unknown option '$1' for uninstall" ;;
        esac
    done
    check_root_only
    take_lock
    trap on_exit EXIT
    if [ "$keep_data" = 1 ]; then
        remove_installation 0
        say "uninstalled; the data directory $DATA_DIR was kept"
    else
        remove_installation 1
        say "uninstalled; the service, files, data directory and account are gone"
    fi
}

# ---- main ----------------------------------------------------------------

[ "$BOOTSTRAP_FORMAT" = 1 ] || die "this script was not generated by a controller"
CMD=${1:-help}
[ $# -eq 0 ] || shift
case $CMD in
    help | -h | --help) usage ;;
    check) cmd_check ;;
    install) cmd_install "$@" ;;
    identity) cmd_identity ;;
    rollback) cmd_rollback ;;
    uninstall) cmd_uninstall "$@" ;;
    *) usage_error "unknown command '$CMD'" ;;
esac
